        presets?: boolean;
        /** @description `next_cursor` from a previous answer: the older rows, unbounded by `minutes` */
        cursor?: string | null;
        /** @description Full-text search over the transcript, notes and the recorded talkgroup alias, using PostgreSQL websearch syntax: `"quoted phrase"`, `or`, `-negated`. */
        q?: string | null;
        /** @description Also match spelling variants of the words in `q` that the archive's transcripts contain (speech-to-text writes `Milrose` for Melrose). Each word of four or more letters, without digits and not negated, is widened to at most 8 vocabulary words within one edit (two for words over five letters). Default false: without it `q` matches exactly as it always has. No effect without `q`. */
        fuzzy?: boolean;
        /** @description Explicit `calls.id` values; repeat for OR. Narrows whatever the other filters already match, so it means "these, out of those". At most 1000 per request (422 over) — past that, describe the set with filters instead. */
        ids?: number[] | null;
        /** @description Inclusive start. A date (local day) or an ISO timestamp; naive = local time (TZ). */
        date_from?: string | null;
        /** @description Inclusive end. A bare date means the end of that local day. */
        date_to?: string | null;
        /** @description Start time of day (HH:MM) on the local clock; wraps midnight when after time_to */
        time_from?: string | null;
        /** @description End time of day (HH:MM) on the local clock */
        time_to?: string | null;
        /** @description Day of week on the local clock, 0 = Sunday; repeat for OR */
        dow?: number[] | null;
        /** @description System id or name; repeat for OR */
        system?: string[] | null;
        /** @description Site id or name; repeat for OR */
        site?: string[] | null;
        /** @description Talkgroup, as the **on-air `tgid`** — not this archive's `talkgroups.id`. Matches `calls.talkgroup_ids`, so patched traffic carrying the talkgroup is included. Add `system` to disambiguate a tgid two systems both use. */
        talkgroup?: number[] | null;
        /** @description Radio, as `radios.id` or the on-air `radio_id` */
        radio?: number[] | null;
        /** @description Apparatus id on the radio (`radios.unit_id`) */
        unit?: string[] | null;
        /** @description Agency code, short name or name; matched through `talkgroups.agency_code` */
        agency?: string[] | null;
        /** @description Talkgroup category (law/fire/ems/pw/transit/interop/…) */
        category?: string[] | null;
        /** @description `group`, `patch` or `individual` */
        call_type?: string[] | null;
        /** @description `group` for traffic on a talkgroup (the default for everything the archive held before private calls were recordable) or `unit` for a P25 unit-to-unit **private call** — one radio to one radio, on no talkgroup. Repeat for OR. Not the same axis as `call_type`, which says how the channel was granted. */
        kind?: string[] | null;
        /** @description Only emergency calls (true) or only non-emergency (false). The flag comes from a trunk-recorder sidecar or a push; an sdrtrunk file cannot carry one, so those calls match neither value. */
        emergency?: boolean | null;
        /** @description Only encrypted calls (true) or only clear (false). An encrypted call is kept for its metadata and has no audio (§1.7). */
        encrypted?: boolean | null;
        /** @description Only calls the audio-processing pass found a sustained tone in (true), or only those it did not (false). A call that has not been processed yet reads false (§5.5). */
        tone_detected?: boolean | null;
        /** @description Only pages (true) — a two-tone or alert pattern in the first seconds of the call. Not the same as `emergency`, which is the flag the radio asserted. */
        alert?: boolean | null;
        /** @description Only calls whose recording is on hand (true → `audio_state='present'`) or only the metadata-only rows (false → archived or purged, which is how an encrypted call is kept). Omit for both (§1.7, §5.3). */
        has_audio?: boolean | null;
        /** @description `analog`, `digital` or `digital tdma`; repeat for OR */
        audio_type?: string[] | null;
        /** @description Minimum duration in seconds */
        min_duration?: number | null;
        /** @description Maximum duration in seconds */
        max_duration?: number | null;
        /** @description pending/queued/running/done/skipped/failed/empty */
        transcript_status?: string[] | null;
        /** @description good/suspect/noise */
        quality?: string[] | null;
        /** @description How the call reached the archive: `live` (recorded as it happened), `backlog` or `bulk` (pushed by an archive migration long afterwards). Repeat for OR. Reads `calls.ingest_priority`, the admission class the push path recorded; `urgent` reads back as `live` and a bare integer is judged against the same band edges the transcription queue uses. Calls the file watcher picked up off disk carry no class and match none of the three. */
        priority?: string[] | null;
        /** @description User tag; repeat for OR */
        tag?: string[] | null;
        /** @description Only starred (true) or only unstarred (false) */
        starred?: boolean | null;
        /** @description Patch, as `patches.id` or the on-air patch number */
        patch?: number[] | null;
        /** @description Conversation id */
        conversation?: number[] | null;
        /** @description Include calls the dedupe marked as duplicates of another (default false) */
        include_duplicates?: boolean;
        /** @description Let `agency` also match talkgroups flagged `shared` — the county dispatch and interop channels no single department owns. Default false, because a shared channel is not that agency's traffic and counting it as such would silently change what every existing `?agency=` query means. Has no effect without `agency`. */
        include_shared?: boolean;
        /** @description Sort key, `-` prefixed for descending. One of: duration, duration_s, id, ingested_at, quality, radio, recorded_at, started_at, started_local, talkgroup, transcript_status. Default `-started_at`. */
